          break
    uniq=[]
    for b in boxes:
     if b not in uniq: uniq.append(b)
    for r0,c0,r1,c1,c in uniq:
     inside=[(r,x) for r in range(r0+1,r1) for x in range(c0+1,c1) if g[r][x] not in (0,c)]
     # remove interior original marks; markers are arranged in regular pattern matching scattered noise color
     for r,x in inside: g[r][x]=0
